    case 991:
      ACCEPT_TOKEN(sym_block_comment);
      END_STATE();
    case 992:
      ACCEPT_TOKEN(anon_sym_POUNDif);
      END_STATE();
    case 993:
      ACCEPT_TOKEN(anon_sym_POUNDelseif);
      END_STATE();
    case 994:
      ACCEPT_TOKEN(anon_sym_POUNDelse);
      if (lookahead == 'i') ADVANCE(87);
